      heroSummary: '位于阿尔及利亚东南角紧邻利比亚边境的塔西利阿杰尔高原，是全球最狂野也最震撼的撒哈拉自然与史前文明终极圣殿。在约一万至五千年前撒哈拉还是一片河湖与疏林草原的“绿色撒哈拉”时期，古人类在高达数百座风蚀砂岩石柱迷宫间刻绘了超过1.5万幅长颈鹿、河马、游牧牛群与神秘圆头人物岩画；而今日高原之下则是塔德拉尔特（Tadrart Rouge）深如血液的赤红沙浪与拔地而起的黑色蘑菇岩塔、天然巨石凯旋门与撒哈拉最令摄影师魂牵梦萦的“泪牛”史前浮雕。',
